-- Colonnes des tables lues par public.scg_5c_inputs, relevées en prod le 25/11/2026 (types seulement, sans contraintes).
-- Sert uniquement à la simulation PGlite de la migration 085.
CREATE TABLE public.profiles (
  id uuid PRIMARY KEY,
  email text,
  full_name text,
  phone text,
  user_type text,
  country text,
  city text,
  address text,
  avatar_url text,
  bio text,
  is_verified boolean,
  rating numeric(3,2),
  total_reviews integer,
  production_type text,
  surface_area numeric(10,2),
  craft_type text,
  experience_years integer,
  member_count integer,
  registration_number text,
  created_at timestamp with time zone,
  updated_at timestamp with time zone,
  is_suspended boolean,
  suspended_reason text,
  suspended_at timestamp with time zone,
  suspended_by uuid,
  scg_criteria jsonb,
  scg_score integer,
  onboarding_completed boolean,
  interests text[],
  scg_badge text,
  scg_bancable boolean,
  scg_calculated_at timestamp with time zone,
  sub_type text,
  profile_completion_pct integer,
  auth_method text,
  preferred_language text,
  onboarding_completed_at timestamp with time zone,
  onesignal_player_id text,
  surface_ha numeric(8,2),
  filieres text[],
  mode_culture text,
  certif_bio boolean,
  certif_fairtrade boolean,
  annee_debut_activite integer,
  coordonnees_gps text,
  rccm_numero text,
  rccm_verified boolean,
  nb_membres integer,
  nb_hectares_total numeric(10,2),
  president_name text,
  secretary_name text,
  commercial_contact text,
  coop_type text,
  zones_production text[],
  capacite_stockage_tonnes numeric(8,2),
  a_vehicule_transport boolean,
  coop_id uuid,
  subscription_tier text,
  linked_email text,
  phone_verified boolean,
  digest_enabled boolean,
  digest_last_sent_at timestamp with time zone,
  latitude double precision,
  longitude double precision,
  location_updated_at timestamp with time zone,
  email_linked_at timestamp with time zone,
  phone_linked_at timestamp with time zone,
  subscription_expires_at timestamp with time zone,
  pricing_plan_id uuid,
  notify_push boolean,
  notify_sms boolean
);
CREATE TABLE public.orders (
