CREATE TABLE public.disputes (
  id uuid PRIMARY KEY,
  order_id uuid,
  opened_by uuid,
  reason text,
  description text,
  evidence_urls jsonb,
  status text,
  resolution text,
  refund_amount numeric(12,2),
  assigned_to uuid,
  created_at timestamp with time zone,
  updated_at timestamp with time zone,
  resolved_at timestamp with time zone
);
CREATE TABLE public.reviews (
  id uuid PRIMARY KEY,
